import json
from fractions import Fraction
from itertools import permutations
from pathlib import Path

import common

ROOT = Path(__file__).resolve().parent.parent
DATA_DIR = ROOT / "data"


class FeatureDef(object):
    def __init__(self, name, I_mask, coeff_vec, mode="base"):
        self.name = name
        self.I_mask = I_mask
        self.coeff_vec = coeff_vec  # list[(u,v,coef)] for u<=v
        self.mode = mode

    def eval(self, omega):
        a = [w * w for w in omega]
        r = len(common.subset_bits(self.I_mask))
        if r == 0 or r > 2:
            return Fraction(0)
        x = sum(a[i] for i in common.subset_bits(self.I_mask))
        b = Fraction(0)
        for pmask in common.iter_subsets(3, 0, 3):
            s = Fraction(0)
            for j in common.subset_bits(pmask):
                s += a[3 + j]
            t = x - s
            if t > 0:
                sign = Fraction(-1) ** (len(common.subset_bits(pmask)))
                b += sign * t ** 3
        poly = Fraction(0)
        for u, v, c in self.coeff_vec:
            poly += c * (omega[u] * omega[v] if u == v else omega[u] * omega[v])
        return b * poly


def _fraction(v):
    if isinstance(v, str):
        return common.parse_fraction(v)
    return Fraction(v)


def _orbit_vectors_for_I(I_mask):
    # monomial orbits under Stab(I) x S(P)
    comp = [i for i in [0, 1, 2] if i not in common.subset_bits(I_mask)]
    perms_m = list({tuple(p) for p in permutations(comp)})
    if not perms_m:
        perms_m = [tuple()]
    perms_p = list(permutations([0, 1, 2]))

    pairs = [(u, v) for u in range(6) for v in range(u, 6)]
    orbits = {}

    def pmove(i, pm):
        if i in common.subset_bits(I_mask):
            return i
        if i < 3:
            if comp:
                return pm[comp.index(i)]
            return i
        return 3 + perms_p[0][i - 3]

    for pair in pairs:
        pts = []
        for pm in perms_m:
            for pp in perms_p:
                u, v = pair
                uu = pmove(u, pm)
                vv = pmove(v, pm)
                # swap of plus indices
                if uu >= 3:
                    uu = 3 + pp[uu - 3]
                if vv >= 3:
                    vv = 3 + pp[vv - 3]
                if uu > vv:
                    uu, vv = vv, uu
                pts.append((uu, vv))
        keyset = tuple(sorted(set(pts)))
        orbits[keyset] = orbits.get(keyset, 0) + 1

    out = []
    for orbit in orbits:
        coeffs = {}
        for u, v in orbit:
            coeffs[(u, v)] = coeffs.get((u, v), 0) + 1
        out.append([(u, v, c) for (u, v), c in sorted(coeffs.items())])
    return out


def build_features(max_r, include_swapped=True):
    defs = []
    seen = set()
    for r in range(1, max_r + 1):
        for I_mask in common.iter_subsets(3, r, r):
            for vec in _orbit_vectors_for_I(I_mask):
                key = tuple(vec)
                if key not in seen:
                    defs.append(FeatureDef("r%d_I%02d_%d" % (r, I_mask, len(seen)), I_mask, vec, "base"))
                    seen.add(key)
                if include_swapped:
                    swap_vec = []
                    for u, v, c in vec:
                        uu = u + 3 if u < 3 else u - 3
                        vv = v + 3 if v < 3 else v - 3
                        if uu > vv:
                            uu, vv = vv, uu
                        swap_vec.append((uu, vv, c))
                    sw_key = tuple(swap_vec)
                    if sw_key not in seen:
                        defs.append(FeatureDef("r%d_I%02d_%d_swap" % (r, I_mask, len(seen)), I_mask, swap_vec, "swap"))
                        seen.add(sw_key)
    return defs


def _canonical_omega_row(omega):
    m_idx = common.sort_partition_idx(omega, [0, 1, 2])
    p_idx = common.sort_partition_idx(omega, [3, 4, 5])
    return [omega[i] for i in (m_idx[0], m_idx[1], m_idx[2], p_idx[0], p_idx[1], p_idx[2])]


def _row_features(omega, features):
    omega = [Fraction(x) for x in omega]
    base = _canonical_omega_row(omega)
    swapped = base[3:] + base[:3]
    vals = []
    for f in features:
        vals.append(f.eval(swapped if f.mode == "swap" else base))
    return vals


def _load_samples(path):
    rows = []
    with open(path, "r") as f:
        for ln in f:
            if not ln.strip():
                continue
            rows.append(json.loads(ln))
    return rows


def _build_dataset(rows, features):
    xs = []
    ys = []
    base_ids = []
    for rec in rows:
        try:
            omega = [_fraction(v) for v in rec["omega"]]
            y = _fraction(rec["A_im"])
        except Exception:
            continue
        feats = _row_features(omega, features)
        if all(v == 0 for v in feats):
            continue
        xs.append(feats)
        ys.append(y)
        base_ids.append(rec["base_id"])
    return xs, ys, base_ids


def _solve_linear_exact(A, b):
    m = len(A)
    n = len(A[0])
    aug = [list(A[i]) + [b[i], i] for i in range(m)]
    row = 0
    pivots = [-1] * n
    for col in range(n):
        p = None
        for r in range(row, m):
            if aug[r][col] != 0:
                p = r
                break
        if p is None:
            continue
        aug[row], aug[p] = aug[p], aug[row]
        pv = aug[row][col]
        aug[row] = [x / pv for x in aug[row]]
        for rr in range(m):
            if rr == row:
                continue
            f = aug[rr][col]
            if f == 0:
                continue
            aug[rr] = [a - f * bb for a, bb in zip(aug[rr], aug[row])]
        pivots[col] = row
        row += 1

    for r in range(m):
        if all(aug[r][c] == 0 for c in range(n)) and aug[r][n] != 0:
            return None, {"status": "inconsistent", "row": r}

    x = [Fraction(0) for _ in range(n)]
    for col in range(n - 1, -1, -1):
        p = pivots[col]
        if p == -1:
            continue
        x[col] = aug[p][n]
    rank = 0
    for p in pivots:
        if p != -1:
            rank += 1
    return x, {"status": "ok", "rank": rank, "n": n, "pivots": pivots}


def _residual_summary(vals):
    if not vals:
        return {"count": 0, "max_abs": "0", "mean_abs": "0"}
    av = [abs(v) for v in vals]
    return {
        "count": len(vals),
        "max_abs": common.frac_to_str(max(av)),
        "mean_abs": common.frac_to_str(sum(av, Fraction(0)) / len(av)),
    }


def _eval(coeffs, F, y):
    out = []
    for f, yy in zip(F, y):
        pred = sum(ci * xi for ci, xi in zip(coeffs, f))
        out.append(yy - pred)
    return out


def _fit_with_split(rows, features):
    X, y, base_ids = _build_dataset(rows, features)
    bases = sorted(set(base_ids))
    n_train = max(1, int(0.75 * len(bases)))
    train_bases = set(bases[:n_train])
    tr_idx = [i for i, b in enumerate(base_ids) if b in train_bases]
    te_idx = [i for i, b in enumerate(base_ids) if b not in train_bases]

    Xtr = [X[i] for i in tr_idx]
    ytr = [y[i] for i in tr_idx]
    coeffs, meta = _solve_linear_exact(Xtr, ytr)
    if coeffs is None:
        return None, {"status": "inconsistent", "train_count": len(tr_idx), "test_count": len(te_idx), "info": meta}

    rtr = _eval(coeffs, Xtr, ytr)
    rte = _eval(coeffs, [X[i] for i in te_idx], [y[i] for i in te_idx]) if te_idx else []
    return coeffs, {
        "status": "ok",
        "feature_count": len(features),
        "train_count": len(tr_idx),
        "test_count": len(te_idx),
        "train_residuals": _residual_summary(rtr),
        "test_residuals": _residual_summary(rte),
        "rank": meta["rank"],
    }


def _evaluate_wall_approaches(coeffs, features):
    path = DATA_DIR / "wall_approaches.json"
    if not path.exists():
        return {"status": "missing wall_approaches.json"}
    payload = json.load(open(path, "r"))
    out = []
    for e in payload:
        rows = e.get("samples", [])

        out_rows = []
        for s in rows:
            omega = [_fraction(x) for x in s["omega"]]
            y = _fraction(s["A_im"])
            feats = _row_features(omega, features)
            pred = sum(ci * xi for ci, xi in zip(coeffs, feats))
            out_rows.append({"sample_id": s.get("sample_id"), "residual": common.frac_to_str(y - pred)})
        out.append({"orbit": e.get("orbit"), "found": e.get("found"), "rows": out_rows})
    return {"count": len(out), "rows": out}


def main():
    sample_path = DATA_DIR / "oracle_samples.jsonl"
    rows = _load_samples(sample_path)
    features_min = build_features(1, include_swapped=True)
    features_ext = build_features(2, include_swapped=True)

    report = {
        "basis_counts": {
            "r1_only": len(features_min),
            "r1_r2": len(features_ext),
        },
        "r1": {},
        "r2": {},
    }

    for tag, feats in (("r1", features_min), ("r2", features_ext)):
        coeffs, fit = _fit_with_split(rows, feats)
        e = {"feature_count": len(feats), "fit": fit}
        if coeffs is None:
            e["status"] = "inconsistent"
            e["first_contradiction"] = fit.get("info", {})
        else:
            e["status"] = "consistent"
            e["coefficients"] = {f.name: common.frac_to_str(c) for f, c in zip(feats, coeffs) if c != 0}
            e["wall_approach_eval"] = _evaluate_wall_approaches(coeffs, feats)
        report[tag] = e

    (DATA_DIR / "h1_fit_report.json").write_text(json.dumps(report, indent=2))
    with (DATA_DIR / "h1_fit_report.txt").open("w") as f:
        f.write("r1 basis = %d\n" % report["basis_counts"]["r1_only"])
        f.write("r1+r2 basis = %d\n" % report["basis_counts"]["r1_r2"])
        f.write("r1 status=%s\n" % report["r1"]["status"])
        f.write("r2 status=%s\n" % report["r2"]["status"])
        if report["r1"].get("fit"):
            f.write("r1 train max abs residual=%s\n" % report["r1"]["fit"].get("train_residuals", {}).get("max_abs", "0"))
        if report["r2"].get("fit"):
            f.write("r2 train max abs residual=%s\n" % report["r2"]["fit"].get("train_residuals", {}).get("max_abs", "0"))
            f.write("r2 test max abs residual=%s\n" % report["r2"]["fit"].get("test_residuals", {}).get("max_abs", "0"))


