import json
from fractions import Fraction
from pathlib import Path

import common
import exact_oracle

ROOT = Path(__file__).resolve().parent.parent
DATA_DIR = ROOT / "data"


def _wall_orbits(wall_catalog):
    buckets = {}
    for entry in wall_catalog:
        orbit = tuple(entry["subset_size_orbit"])
        buckets.setdefault(tuple(orbit), []).append(entry)
    return buckets


def _free_from_t(t: float, a: Fraction, b: Fraction, fam: int = 0):
    if fam == 0:
        # one-parameter family
        return [
            Fraction.from_float(t),
            Fraction.from_float(-a + t),
            Fraction(2, 1),
            Fraction(1, 1),
        ]
    if fam == 1:
        return [
            Fraction.from_float(t),
            Fraction.from_float(-a - t),
            Fraction.from_float(b + 2 * t),
            Fraction.from_float(-1),
        ]
    return [
        Fraction(1, 1),
        Fraction.from_float(-1),
        Fraction.from_float(b * t),
        Fraction.from_float(a),
    ]


def _sample_q_value(omega, entry):
    return common.wall_value([w * w for w in omega], int(entry["I_mask"]), int(entry["J_mask"]))


def _sign_changes(values):
    prev = values[0]
    for i in range(1, len(values)):
        cur = values[i]
        if prev == 0 or cur == 0:
            return True
        if prev * cur < 0:
            return True
        prev = cur
    return False


def _search_root(entry, fam):
    wall_id = str(entry["id"])
    a = Fraction(1, 1)
    b = Fraction(1, 1)
    samples = []
    for t in [i / 40 for i in range(-120, 121)]:
        free = _free_from_t(float(t) / 20.0, a, b, fam)
        try:
            omega = list(common.solve_from_free(free, common.SIG_FULL))
        except Exception:
            continue
        q = _sample_q_value(omega, entry)
        samples.append((float(t), omega, q))
        # skip degeneracies
        if q == 0:
            continue
    vals = [s[2] for s in samples]
    if len(vals) < 4:
        return None
    if not _sign_changes(vals):
        return None
    # find first interval with sign change
    for k in range(1, len(samples)):
        if samples[k - 1][2] == 0 or samples[k][2] == 0:
            return samples[k - 1][0], samples[k - 1][0]
        if samples[k - 1][2] * samples[k][2] < 0:
            lo_t, lo_om, lo_q = samples[k - 1]
            hi_t, hi_om, hi_q = samples[k]
            break
    else:
        return None
    lo = lo_t
    hi = hi_t
    for _ in range(60):
        mid = 0.5 * (lo + hi)
        free = _free_from_t(mid, a, b, fam)
        try:
            om = list(common.solve_from_free(free, common.SIG_FULL))
            q = _sample_q_value(om, entry)
        except Exception:
            lo = mid
            continue
        if lo_q * q <= 0:
            hi = mid
            hi_om = om
            hi_q = q
        else:
            lo = mid
            lo_om = om
            lo_q = q
    return (0.5 * (lo + hi),)


def main():
    wall_catalog = common.build_wall_catalog()
    orbit_map = _wall_orbits(wall_catalog)
    wall_catalog_path = DATA_DIR / "wall_catalog.json"
    if not wall_catalog_path.exists():
        raise RuntimeError("wall_catalog.json missing; run domain_scan first")
    with wall_catalog_path.open() as f:
        existing = json.load(f)
    if existing.get("count", 0) == 0:
        raise RuntimeError("empty wall catalog")

    out_rows = []
    for orbit, entries in sorted(orbit_map.items(), key=lambda kv: kv[0]):
        representative = entries[0]
        found = False
        for fam in range(2):
            root = _search_root(representative, fam)
            if root is not None:
                t0 = root[0]
                found = True
                break
        if not found:
            out_rows.append(
                {
                    "orbit": f"{orbit}",
                    "found": False,
                    "wall_ids": [str(x["id"]) for x in entries],
                    "samples": [],
                    "note": "no robust wall root located on scanned family",
                }
            )
            continue

        # Evaluate both sides on rational offsets
        deltas = [Fraction(1, 100), Fraction(1, 1000), Fraction(1, 10000), Fraction(1, 100000)]
        samples = []
        for sign in (-1, 1):
            for d in deltas:
                t = Fraction.from_float(t0) + Fraction(sign) * d
                free = _free_from_t(float(t), Fraction(1, 1), Fraction(1, 1), 0)
                try:
                    omega = list(common.solve_from_free(free, common.SIG_FULL))
                except Exception:
                    continue
                try:
                    out = exact_oracle.evaluate_omega(omega, f"wall-{orbit}-{sign}-{d}", wall_catalog)
                except Exception:
                    continue
                q = _sample_q_value(omega, representative)
                wv = {str(k["id"]): common.frac_to_str(_sample_q_value(omega, k)) for k in entries}
                wsign = {k: (1 if common.parse_fraction(v) > 0 else -1) for k, v in wv.items()}
                out_rows_entry = {
                    "orbit": f"{orbit}",
                    "wall_id": str(representative["id"]),
                    "q": common.frac_to_str(q),
                    "A_im": common.frac_to_str(out.A_im),
                    "free_w": [common.frac_to_str(x) for x in free],
                    "omega": [common.frac_to_str(x) for x in omega],
                    "wall_signature": out.canonical_wall_signature,
                    "wall_signs": wsign,
                }
                samples.append(out_rows_entry)
        out_rows.append(
            {
                "orbit": f"{orbit}",
                "found": True,
                "wall_ids": [str(x["id"]) for x in entries],
                "t_root": str(t0),
                "samples": samples,
            }
        )

    (DATA_DIR / "wall_approaches.json").write_text(json.dumps(out_rows, indent=2))


