class FeatureDef(object):
    def __init__(self, name, I_mask, I_mask_swap, base_pairs, swap_pairs):
        self.name = name
        self.I_mask = I_mask
        self.I_mask_swap = I_mask_swap
        self.base_pairs = base_pairs
        self.swap_pairs = swap_pairs

    def _b_factor(self, omega_sq, I_indices, target_indices):
        x = sum(omega_sq[i] for i in I_indices)
        out = Fraction(0)
        target = tuple(target_indices)
        for r in range(len(target) + 1):
            for idxs in combinations(target, r):
                s = sum(omega_sq[i] for i in idxs)
                sign = Fraction(-1) if (r % 2 == 1) else Fraction(1)
                out += sign * (x - s) ** 3
        return out

    def _pair_sum(self, omega, pairs):
        return sum(Fraction(omega[u]) * Fraction(omega[v]) for u, v in pairs)

    def eval(self, omega):
        omega = [Fraction(w) for w in omega]
        omega_sq = [w * w for w in omega]

        p_base = self._pair_sum(omega, self.base_pairs)
        p_swap = self._pair_sum(omega, self.swap_pairs)

        I_base = common.subset_bits(self.I_mask)
        I_swap = tuple(i + 3 for i in common.subset_bits(self.I_mask_swap))

        b_base = self._b_factor(omega_sq, I_base, (3, 4, 5))
        b_swap = self._b_factor(omega_sq, I_swap, (0, 1, 2))

        return b_base * p_base + b_swap * p_swap


