    q = Fraction(0)
    for i in range(len(omega)):
        if (mask >> i) & 1:
            q += signs[i] * omega[i] * omega[i]
    return q


def h_T(omega, mask, signs):
    q = q_T_for_mask(omega, mask, signs)
    wsum = sum(omega[i] for i in range(len(omega)) if (mask >> i) & 1)
    h = wsum * wsum - abs(q)
    return h, q
